// Strict Aliasing Rule Violation (UB Example)

// Storage defined as int
int storage = 100;

// Incompatible type cast (Violation unless char* or allowed base)
float* alias_ptr = reinterpret_cast<float*>(&storage);

// Write via incompatible type
*alias_ptr = 5.5f;

// Compiler (O2/O3) assumes storage (int) is unaffected by alias_ptr (float*).
// The read of 'storage' might yield 100, ignoring the mutation.

int result = storage; // RESULT: Undefined Behavior
                      // Compiler assumes 'alias_ptr' cannot alias 'storage'
                      // unless they are compatible types.

// EXCEPTION: char* pointers (or std::byte) are always allowed to alias.
char* char_ptr = reinterpret_cast<char*>(&storage); // Safe access
